"""Persistent reservation controller: leases, revisions, edits and compilation."""

import schema as S
from schema import Bad
from planner import compile_plan

PROTOCOL = 'forest-controller/3'
NOT_LOADED = {'status': 'error', 'code': 'NOT_LOADED', 'rev': 0}


def err(code, r):
    return {'status': 'error', 'code': code, 'rev': r}


def stale(r):
    return {'status': 'stale', 'rev': r}


class Controller:
    def __init__(self):
        self.loaded = False
        self.R = 0
        self.T = 0
        self.n = 0
        self.links = []
        self.cap = []
        self.bookings = {}
        self.load_ids = set()
        self.preps = {}

    # ---------------- helpers ----------------
    def usage(self, t, only=None):
        used = [0] * len(self.links)
        for bid, b in self.bookings.items():
            if not b['live']:
                continue
            if b['s'] <= t < b['e']:
                for l, r in b['env'].items():
                    used[l] += r
        return used

    def overbook_witness(self, caps):
        """First (link,time,used,cap) with used>proposed cap at some t>=T."""
        ticks = [self.T]
        for b in self.bookings.values():
            if b['live'] and b['s'] > self.T:
                ticks.append(b['s'])
        for t in sorted(set(ticks)):
            used = self.usage(t)
            for l, c in sorted(caps.items()):
                if used[l] > c:
                    return (l, t, used[l], c)
        return None

    def fit_witness(self, s, e, env):
        """First (link,time,total,cap) where offered envelope does not fit."""
        ticks = [s]
        for b in self.bookings.values():
            if not b['live']:
                continue
            if s < b['s'] < e:
                ticks.append(b['s'])
        for t in sorted(set(ticks)):
            if t >= e:
                continue
            used = self.usage(t)
            for l, b_l in sorted(env.items()):
                tot = used[l] + b_l
                if tot > self.cap[l]:
                    return (l, t, tot, self.cap[l])
        return None

    # ---------------- dispatch ----------------
    def handle(self, req):
        try:
            return self.dispatch(req)
        except Bad:
            return {'status': 'invalid'}

    def dispatch(self, req):
        if not isinstance(req, dict):
            raise Bad('not an object')
        op = req.get('op')
        if not isinstance(op, str):
            raise Bad('op type')
        if op == 'about':
            S.keys(req, ['op'])
            return {'status': 'ok', 'protocol': PROTOCOL}
        if op == 'load':
            return self.do_load(req)
        if op == 'audit':
            return self.do_audit(req)
        if op == 'advance':
            return self.do_advance(req)
        if op == 'edit':
            return self.do_edit(req)
        if op == 'prepare':
            return self.do_prepare(req)
        if op == 'commit':
            return self.do_commit(req)
        if op == 'cancel':
            return self.do_cancel(req)
        raise Bad('unknown op')

    # ---------------- load ----------------
    def do_load(self, req):
        S.keys(req, ['op', 'n', 'links', 'bookings'])
        n = S.integer(req['n'], 2, 48)
        raw = req['links']
        if not isinstance(raw, list) or len(raw) > 128:
            raise Bad('links')
        links = []
        seen = set()
        for item in raw:
            if not isinstance(item, list) or len(item) != 3:
                raise Bad('link shape')
            u = S.node(item[0])
            v = S.node(item[1])
            c = S.amount(item[2])
            if u >= n or v >= n or u == v:
                raise Bad('link endpoints')
            k = (u, v) if u < v else (v, u)
            if k in seen:
                raise Bad('duplicate link')
            seen.add(k)
            links.append((u, v, c))
        rawb = req['bookings']
        if not isinstance(rawb, list) or len(rawb) > 128:
            raise Bad('bookings')
        nl = len(links)
        bookings = []
        ids = set()
        entries = 0
        for b in rawb:
            S.keys(b, ['id', 'owner', 'window', 'envelope'])
            bid = S.ident(b['id'])
            owner = S.ident(b['owner'])
            if bid in ids:
                raise Bad('duplicate booking id')
            ids.add(bid)
            s, e = S.window(b['window'])
            env = S.envelope(b['envelope'], nl)
            entries += len(env)
            bookings.append((bid, owner, s, e, env))
        if entries > 2048:
            raise Bad('too many envelope entries')
        if self.loaded:
            return err('ALREADY_LOADED', self.R)
        # first load: bookings must not overbook the base capacities
        per = [[] for _ in links]
        for bid, owner, s, e, env in bookings:
            for l, r in env.items():
                per[l].append((s, e, r))
        for l, iv in enumerate(per):
            if not iv:
                continue
            cap = links[l][2]
            ev = []
            for s, e, r in iv:
                ev.append((s, -r))
                ev.append((e, r))
            ev.sort()
            cur = 0
            for _t, d in ev:
                cur += d
                if cur > cap:
                    raise Bad('overbooked')
        self.loaded = True
        self.n = n
        self.links = [(u, v) for (u, v, c) in links]
        self.cap = [c for (u, v, c) in links]
        self.R = 0
        self.T = 0
        self.bookings = {}
        self.load_ids = set()
        for bid, owner, s, e, env in bookings:
            self.bookings[bid] = {'owner': owner, 's': s, 'e': e,
                                 'env': env, 'live': True, 'origin': 'load'}
            self.load_ids.add(bid)
        return {'status': 'ok', 'rev': 0, 'now': 0}

    # ---------------- audit ----------------
    def do_audit(self, req):
        S.keys(req, ['op', 'at'])
        raw = req['at']
        if not isinstance(raw, list) or len(raw) > 8:
            raise Bad('at')
        ticks = [S.tick(t) for t in raw]
        if not self.loaded:
            return dict(NOT_LOADED)
        for t in ticks:
            if t < self.T:
                return err('TIME', self.R)
        m = len(self.links)
        samples = []
        for t in ticks:
            used = self.usage(t)
            samples.append([t, [self.cap[l] - used[l] for l in range(m)]])
        leases = sorted(bid for bid, b in self.bookings.items() if b['live'])
        return {'status': 'ok', 'rev': self.R, 'now': self.T,
                'leases': leases, 'samples': samples}

    # ---------------- advance ----------------
    def do_advance(self, req):
        S.keys(req, ['op', 'time'])
        t = S.tick(req['time'])
        if not self.loaded:
            return dict(NOT_LOADED)
        if t < self.T:
            return err('TIME', self.R)
        self.T = t
        expired = []
        for bid, b in self.bookings.items():
            if b['live'] and b['e'] <= t:
                b['live'] = False
                expired.append(bid)
        self.R += 1
        return {'status': 'ok', 'rev': self.R, 'now': t,
                'expired': sorted(expired)}

    # ---------------- edit ----------------
    def do_edit(self, req):
        S.keys(req, ['op', 'rev', 'changes', 'force'])
        r = S.rev(req['rev'])
        force = S.boolean(req['force'])
        raw = req['changes']
        if not isinstance(raw, list) or len(raw) > 128:
            raise Bad('changes')
        changes = {}
        for item in raw:
            if not isinstance(item, list) or len(item) != 2:
                raise Bad('change shape')
            l = S.link(item[0])
            c = S.amount(item[1])
            if l in changes:
                raise Bad('duplicate change link')
            changes[l] = c
        if not self.loaded:
            return dict(NOT_LOADED)
        if r != self.R:
            return stale(self.R)
        for l in changes:
            if l >= len(self.links):
                return err('REFERENCE', self.R)
        if not force:
            wit = self.overbook_witness(changes)
            if wit is not None:
                l, t, u, c = wit
                return {'status': 'blocked', 'rev': self.R, 'link': l,
                        'time': t, 'used': u, 'capacity': c}
            for l, c in changes.items():
                self.cap[l] = c
            self.R += 1
            return {'status': 'ok', 'rev': self.R, 'cancelled': []}
        decreased = [l for l, c in changes.items() if c < self.cap[l]]
        revoked = []
        if decreased:
            dset = set(decreased)
            for bid, b in self.bookings.items():
                if not b['live']:
                    continue
                for l, rate in b['env'].items():
                    if rate > 0 and l in dset:
                        revoked.append(bid)
                        break
            for bid in revoked:
                self.bookings[bid]['live'] = False
        for l, c in changes.items():
            self.cap[l] = c
        self.R += 1
        return {'status': 'ok', 'rev': self.R, 'cancelled': sorted(revoked)}

    # ---------------- prepare ----------------
    def do_prepare(self, req):
        S.keys(req, ['op', 'id', 'owner', 'window', 'period',
                     'participants', 'envelope', 'rev'])
        pid = S.ident(req['id'])
        owner = S.ident(req['owner'])
        s, e = S.window(req['window'])
        p = S.integer(req['period'], 1, 10 ** 6)
        rawp = req['participants']
        if not isinstance(rawp, list) or len(rawp) < 2 or len(rawp) > 32:
            raise Bad('participants')
        rdem = {}
        for item in rawp:
            if not isinstance(item, list) or len(item) != 2:
                raise Bad('participant shape')
            v = S.node(item[0])
            rv = S.amount(item[1])
            if v in rdem:
                raise Bad('duplicate participant')
            rdem[v] = rv
        total = 0
        for v in rdem:
            total += rdem[v]
        if total <= 0:
            raise Bad('no demand')
        env = S.envelope(req['envelope'])
        r = S.rev(req['rev'])
        if not self.loaded:
            return dict(NOT_LOADED)
        key = (owner, s, e, p, tuple(sorted(rdem.items())),
               tuple(sorted(env.items())), r)
        rec = self.preps.get(pid)
        if rec is not None:
            if rec['key'] == key:
                return {'status': 'replay', 'id': pid, 'rev': self.R,
                        'base_rev': rec['base_rev'], 'outcome': rec['outcome']}
            return err('CONFLICT', self.R)
        if pid in self.load_ids:
            return err('CONFLICT', self.R)
        if r != self.R:
            return stale(self.R)
        for v in rdem:
            if v >= self.n:
                return err('REFERENCE', self.R)
        for l in env:
            if l >= len(self.links):
                return err('REFERENCE', self.R)
        if s < self.T:
            return err('TIME', self.R)
        if (e - s) % p != 0:
            return err('WINDOW', self.R)
        caps = [p * env.get(l, 0) for l in range(len(self.links))]
        wit = self.fit_witness(s, e, env)
        if wit is not None:
            l, t, u, c = wit
            self.preps[pid] = {'key': key, 'outcome': 'denied',
                               'base_rev': self.R, 'owner': owner}
            return {'status': 'denied', 'id': pid, 'rev': self.R,
                    'kind': 'capacity', 'link': l, 'time': t, 'used': u,
                    'capacity': c}
        parts = sorted(rdem)
        kind, payload = compile_plan(self.n, self.links, caps, parts, rdem)
        if kind == 'cut':
            self.preps[pid] = {'key': key, 'outcome': 'denied',
                               'base_rev': self.R, 'owner': owner}
            return {'status': 'denied', 'id': pid, 'rev': self.R,
                    'kind': 'cut', 'cut': list(payload)}
        self.preps[pid] = {'key': key, 'outcome': 'prepared',
                           'base_rev': self.R, 'owner': owner,
                           's': s, 'e': e, 'env': env}
        return {'status': 'prepared', 'id': pid, 'rev': self.R, 'plan': payload}

    # ---------------- commit ----------------
    def do_commit(self, req):
        S.keys(req, ['op', 'id', 'owner', 'rev'])
        cid = S.ident(req['id'])
        owner = S.ident(req['owner'])
        r = S.rev(req['rev'])
        if not self.loaded:
            return dict(NOT_LOADED)
        b = self.bookings.get(cid)
        p = self.preps.get(cid)
        if b is None and p is None:
            return err('MISSING', self.R)
        have = b['owner'] if b is not None else p['owner']
        if have != owner:
            return err('OWNER', self.R)
        if b is not None:
            if b['live']:
                return {'status': 'ok', 'id': cid, 'rev': self.R,
                        'replay': True}
            return err('GONE', self.R)
        if p['outcome'] != 'prepared':
            return err('DENIED', self.R)
        if r != self.R or p['base_rev'] != self.R:
            return stale(self.R)
        self.bookings[cid] = {'owner': owner, 's': p['s'], 'e': p['e'],
                              'env': dict(p['env']), 'live': True,
                              'origin': 'commit'}
        self.R += 1
        return {'status': 'ok', 'id': cid, 'rev': self.R, 'replay': False}

    # ---------------- cancel ----------------
    def do_cancel(self, req):
        S.keys(req, ['op', 'id', 'owner', 'rev'])
        cid = S.ident(req['id'])
        owner = S.ident(req['owner'])
        r = S.rev(req['rev'])
        if not self.loaded:
            return dict(NOT_LOADED)
        if r != self.R:
            return stale(self.R)
        b = self.bookings.get(cid)
        if b is None or not b['live']:
            return err('MISSING', self.R)
        if b['owner'] != owner:
            return err('OWNER', self.R)
        b['live'] = False
        self.R += 1
        return {'status': 'ok', 'rev': self.R, 'released': cid}
