"""Service entry point: JSON lines in, one JSON reply per line out."""
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))
VENDOR = '/workspace/vendor/networkx-3.4.2-py3-none-any.whl'
if VENDOR not in sys.path:
    sys.path.insert(1, VENDOR)

from service import handle
from wire import decode

out = sys.stdout
write = out.write
for line in sys.stdin.buffer:
    try:
        request = decode(line.decode('utf-8'))
        response = handle(request)
    except Exception:
        response = {'status': 'invalid'}
    try:
        write(json.dumps(response, separators=(',', ':')))
        write('\n')
        out.flush()
    except Exception:
        break
